def transform(grid):
    h, w = len(grid), len(grid[0])
    row_lines = [r for r in range(h) if len(set(grid[r])) == 1]
    col_lines = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    # The repeated divider color is the color of full uniform lines.
    line_colors = [grid[r][0] for r in row_lines] + [grid[0][c] for c in col_lines]
    divider = max(set(line_colors), key=line_colors.count)

    row_lines = [r for r in row_lines if grid[r][0] == divider]
    col_lines = [c for c in col_lines if grid[0][c] == divider]

    def period(lines, size):
        if len(lines) >= 2:
            return lines[1] - lines[0]
        if lines:
            return size - lines[0]
        return size

    py = period(row_lines, h)
    px = period(col_lines, w)

    from collections import Counter
    counts = Counter(v for row in grid for v in row if v != divider)
    background = counts.most_common(1)[0][0]

    # Learn the marked pattern at each position modulo the repetition periods.
    pattern = {}
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value != divider and value != background:
                pattern[(r % py, c % px)] = value

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == divider:
                continue
            key = (r % py, c % px)
            if key in pattern:
                out[r][c] = pattern[key]
    return out
